Here is the root cause:
The bug arises from the failure to clear the shadow page table entry after it has been set as post-sync. This oversight can lead to incorrect memory virtualization behavior, as the shadow page table may retain stale or incorrect entries, causing errors during guest operations, particularly in the context of GPU virtualization.

Here is the patch:

 static int ppgtt_handle_guest_write_page_table_bytes(void *gp,
 		u64 pa, void *p_data, int bytes)
 {
 	struct intel_vgpu_guest_page *gpt = (struct intel_vgpu_guest_page *)gp;
 	struct intel_vgpu_ppgtt_spt *spt = guest_page_to_ppgtt_spt(gpt);
 	struct intel_vgpu *vgpu = spt->vgpu;
 	struct intel_gvt_gtt_pte_ops *ops = vgpu->gvt->gtt.pte_ops;
 	const struct intel_gvt_device_info *info = &vgpu->gvt->device_info;
 	struct intel_gvt_gtt_entry we, se;
 	unsigned long index;
 	int ret;

 	index = (pa & (PAGE_SIZE - 1)) >> info->gtt_entry_size_shift;

 	ppgtt_get_guest_entry(spt, &we, index);

 	ops->test_pse(&we);

 	if (bytes == info->gtt_entry_size) {
 		ret = ppgtt_handle_guest_write_page_table(gpt, &we, index);
 		if (ret)
 			return ret;
 	} else {
 		if (!test_bit(index, spt->post_shadow_bitmap)) {
+			int type = spt->shadow_page.type;
+
 			ppgtt_get_shadow_entry(spt, &se, index);
 			ret = ppgtt_handle_guest_entry_removal(gpt, &se, index);
 			if (ret)
 				return ret;
+			ops->set_pfn(&se, vgpu->gtt.scratch_pt[type].page_mfn);
+			ppgtt_set_shadow_entry(spt, &se, index);
 		}
-
 		ppgtt_set_post_shadow(spt, index);
 	}

 	if (!enable_out_of_sync)
 		return 0;

 	gpt->write_cnt++;

 	if (gpt->oos_page)
 		ops->set_entry(gpt->oos_page->mem, &we, index,
 				false, 0, vgpu);

 	if (can_do_out_of_sync(gpt)) {
 		if (!gpt->oos_page)
 			ppgtt_allocate_oos_page(vgpu, gpt);

 		ret = ppgtt_set_guest_page_oos(vgpu, gpt);
 		if (ret < 0)
 			return ret;
 	}
 	return 0;
 }



